// Детерминированная нормализация сленга КР (Правила именования КР)
const item = $input.first().json;
let text = item.body?.text || "";

if (text) {
  // Защита от искажения англоязычных запросов: если текст не содержит кириллицы, пропускаем русскую нормализацию сленга
  const hasCyrillic = /[а-яА-ЯёЁ]/.test(text);

  if (hasCyrillic) {
    // Защита: если пользователь спрашивает значение самого термина ("что такое ГК", "сокращение ВК")
    const isDefQuery = /\b(?:что (?:такое|за)|сокращени|расшифр|значит)\b/i.test(text);
    const isMep = /\b(?:ОВ\s*\/\s*ВК|ОВ\s+и\s+ВК)\b/i.test(text);

    if (!isDefQuery) {
      text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])ГК(?![A-Za-zА-Яа-я0-9_])/gi, "горизонтальные конструкции");
      if (!isMep) {
        text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])(?<!ОВ\/)(?<!ОВ и )ВК(?![A-Za-zА-Яа-я0-9_])/gi, "вертикальные конструкции");
      }
    } else {
      text = `${text} (Правила именования КР: общепринятые сокращения ГК ВК)`;
    }

    text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])ФП(?![A-Za-zА-Яа-я0-9_])/gi, "фундаментная плита");
    text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])ФО(?![A-Za-zА-Яа-я0-9_])/gi, "фундамент оборудования");
    text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])Лп(?![A-Za-zА-Яа-я0-9_])/g, "лестничная площадка");
    text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])Лм(?![A-Za-zА-Яа-я0-9_])/g, "лестничный марш");
    text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])СТЛБ(?![A-Za-zА-Яа-я0-9_])/gi, "стилобат");
    text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])ПРК(?![A-Za-zА-Яа-я0-9_])/gi, "паркинг");
    text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])Опл(?![A-Za-zА-Яа-я0-9_])/gi, "опалубка");
    text = text.replace(/(?<![A-Za-zА-Яа-я0-9_])Арм(?![A-Za-zА-Яа-я0-9_])/gi, "армирование");

    // Разговорный сленг
    text = text.replace(/\bсборняк(?:а|у|ом|е)?\b/gi, "сборные конструкции сборные элементы");
    text = text.replace(/\bраскидать(?:\s+по\s+осям)?\b/gi, "расставить по осям");
    text = text.replace(/\bавтоматом\b/gi, "автоматически");
    text = text.replace(/\bзеркалить\b/gi, "зеркалировать");
    text = text.replace(/\bна\s+\d+\s+свай\b/gi, "свай");

    // Мягкое синонимическое расширение (Query Expansion)
    if (!/фиксатор/i.test(text)) {
      text = text.replace(/\b(лягушк\w*)\b/gi, "$1 (фиксаторы сеток)");
    }
    if (!/погонн\w*\s+метр/i.test(text)) {
      text = text.replace(/\b(погонаж\w*)\b/gi, "$1 (погонные метры)");
    }
  }
}

return {
  json: {
    ...item,
    body: {
      ...item.body,
      text: text
    }
  }
};
